"""Build/serve a local read-only v8 results gallery. No model calls."""
import argparse,functools,json,sys
from http.server import SimpleHTTPRequestHandler,ThreadingHTTPServer
from pathlib import Path
from urllib.parse import unquote,urlsplit
sys.path.insert(0,str(Path(__file__).resolve().parents[1]/'src'))
from when2ask.config import ROOT
OUT=ROOT/'outputs/three_task_v8';MEDIA=ROOT/'presentation/three_task_v8/media'


def build():
    summary=json.loads((OUT/'report/summary.json').read_text());manifest=json.loads((MEDIA.parent/'media_manifest.json').read_text())
    samples=[]
    for sid in sorted({r['sample_id'] for r in manifest}):
        samples.append(dict(sample_id=sid,template=next(r['template'] for r in manifest if r['sample_id']==sid),
            methods=[dict(**r,episode_path='test_runs/'+sid+'__'+r['method']+'/episode.json') for r in manifest if r['sample_id']==sid]))
    (OUT/'gallery.json').write_text(json.dumps(dict(summary=summary,samples=samples),indent=2)+'\n')
    (OUT/'index.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="data:,"><title>When2Ask v8 · Held-out Benchmark</title><link rel="stylesheet" href="gallery.css"><body><main>
<header><span class="kicker">WHEN2ASK / INDEPENDENT BENCHMARK V8</span><h1>Knowing when to ask.</h1><p>Three task templates · Fresh held-out physical layouts · Real DeepSeek / Jev / PyBullet</p></header>
<section class="stats"><div><strong>24 / 6</strong><span>Dev samples / groups</span></div><div><strong>12 / 12</strong><span>Test samples / groups</span></div><div><strong>36 / 36</strong><span>Real physical oracles</span></div><div><strong id="calls"></strong><span>Authenticated requests / 450</span></div></section>
<section class="panel"><h2>All Test samples, three paired methods</h2><p>Source, data, prompts and threshold 0.5 frozen before model Test. Original 128-Test remains unchanged and unrun.</p><div class="scroll"><table><thead><tr><th>Method</th><th>Success</th><th>Mean burden</th><th>API latency total</th><th>Skill rejections</th></tr></thead><tbody id="results"></tbody></table></div><p class="note">12 independent groups. Confidence intervals are descriptive; no statistical superiority claim. Three rejected panel-placement commands were followed by actual cover repairs; failures remain in the logs.</p><img class="chart" src="report/benchmark_summary.png" alt="Success, burden and agent API latency from all raw trajectories"></section>
<section class="panel" id="recordings"><div class="heading"><div><span class="kicker">REAL EXECUTION EVIDENCE</span><h2>Three methods, one held-out scene</h2></div><select id="case" aria-label="Recorded held-out case"></select></div><p>These three cases were selected for recording before Test, by first undisclosed layout per template. Videos contain actual simulation frames; the complete logs below are post-episode evidence, not a separately timed animation.</p><div class="players" id="players"></div></section>
<section class="panel"><h2>Paired outcomes and exploratory timing</h2><img class="chart narrow" src="report/paired_outcomes.png" alt="Every Test sample paired across three methods"><img class="chart narrow" src="report/clarification_timing.png" alt="Post-Test exploratory first ASK timing relative to opening"><p class="note">Timing analysis uses a public-DAG support reference after Test; it was not a preregistered optimal-timing metric. No hidden preference is used in that reference.</p></section>
<footer><a href="report/report.md">Report</a><a href="report/summary.json">Summary JSON</a><a href="report/episodes.csv">All 36 episode rows</a><a href="frozen_manifest.json">Frozen manifest</a><a href="report/mapping_validation.json">Wire / physics audit</a><p>Small, single-binary-slot benchmark. Correct geometry under a wrong hidden choice still scores unsuccessful. All original studies retained.</p></footer></main><script src="gallery.js"></script></body></html>''')
    (OUT/'gallery.css').write_text('''*{box-sizing:border-box}body{margin:0;background:#eef3f8;color:#24364e;font-family:Arial,sans-serif}main{max-width:1580px;margin:auto;padding:38px}header{padding:12px 0 28px}h1{font-size:48px;letter-spacing:-2px;margin:12px 0;color:#15335b}h2{margin:8px 0 18px;color:#173c65;font-size:25px}p{line-height:1.65;color:#556980}a{color:#2469b3}.kicker{font-size:12px;font-weight:bold;letter-spacing:2px;color:#36779e}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin:0 0 26px}.stats div,.panel{background:white;border:1px solid #dce5ee;border-radius:14px}.stats div{padding:22px}.stats strong{display:block;font-size:32px;color:#163c65}.stats span{display:block;margin-top:10px;font-size:13px;color:#687d92}.panel{padding:26px;margin-bottom:26px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:15px 12px;border-bottom:1px solid #e2e9f0;font-size:16px}th{color:#637c93;font-size:12px;text-transform:uppercase;letter-spacing:1px}.chart{display:block;width:100%;height:auto;margin:24px auto 0}.narrow{max-width:1100px}.note{font-size:13px;color:#6f8093}.heading{display:flex;gap:20px;align-items:center;justify-content:space-between}select{padding:12px;border:1px solid #c5d4e2;border-radius:8px;max-width:100%;background:white;color:#23415f}.players{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.player{border:1px solid #dce5ee;border-radius:12px;overflow:hidden;min-width:0}.player h3{font-size:17px;padding:16px;margin:0;background:#f4f8fc}.player video{width:100%;aspect-ratio:4/3;background:#e9eff6;display:block}.details{padding:16px}.badge{font-size:13px;font-weight:bold;color:#287b57}.badge.fail{color:#b85145}.events{font-size:12px;line-height:1.65;max-height:260px;overflow:auto;margin-top:16px;color:#5d6d7e}.events p{padding:8px 0;margin:0;border-bottom:1px solid #e7edf2;overflow-wrap:anywhere}footer{padding:14px 0 35px;font-size:13px}footer a{display:inline-block;margin:0 20px 12px 0}@media(max-width:850px){main{padding:18px}h1{font-size:35px}.stats{grid-template-columns:repeat(2,1fr)}.players{grid-template-columns:1fr}.heading{align-items:flex-start;flex-direction:column}.panel{padding:18px}th,td{font-size:13px}}''')
    (OUT/'gallery.js').write_text('''const names={llm_noask:'LLM-NoAsk',llm_gate:'LLM-Gate',jev_gate:'Jev-Gate'},$=s=>document.querySelector(s);const element=(tag,text,cls)=>{const e=document.createElement(tag);e.textContent=text;if(cls)e.className=cls;return e};
let data,version=0;async function select(){const token=++version;const selected=data.samples.find(s=>s.sample_id===$('#case').value);const cards=await Promise.all(['llm_noask','llm_gate','jev_gate'].map(async method=>{const media=selected.methods.find(r=>r.method===method),e=await(await fetch(media.episode_path)).json();const card=element('article','','player');card.dataset.method=method;card.append(element('h3',names[method]));const video=document.createElement('video');video.controls=true;video.preload='metadata';video.src='/media/'+media.file;video.onloadedmetadata=()=>{video.playbackRate=2;};card.append(video);const body=element('div','','details');body.append(element('div',e.evaluation.task_success?'TASK SUCCESS':'TASK UNSUCCESSFUL','badge'+(e.evaluation.task_success?'':' fail')),element('p','Burden '+e.evaluation.clarification_burden+' · Commands '+e.actions.length+' · API '+(e.cost.api_latency_ms/1000).toFixed(2)+'s'));const link=element('a','Episode JSON ↗');link.href=media.episode_path;link.target='_blank';body.append(link);const events=element('div','','events');for(const t of e.turns){let text='Round '+t.round+' · '+(t.gate.called?(t.gate.p_ask==null?'Gate':'Jev p='+t.gate.p_ask.toFixed(2))+' → '+t.gate.decision:'No gate');if(t.question)text+=' · ASK: '+t.question.text+' · USER: '+JSON.stringify(t.user_answer);if(t.action)text+=' · '+JSON.stringify(t.action);if(t.physical_result)text+=' · '+(t.physical_result.success?'succeeded':'failed: '+t.physical_result.reason);events.append(element('p',text));}body.append(events);card.append(body);return card}));if(token===version){$('#players').replaceChildren(...cards);window.galleryCaseReady=selected.sample_id;}}
(async()=>{data=await(await fetch('gallery.json')).json();$('#calls').textContent=data.summary.total_authenticated_requests;for(const r of data.summary.methods){const tr=document.createElement('tr');for(const value of [names[r.method],r.successes+'/12',r.burden_mean.toFixed(3),r.api_latency_s.toFixed(2)+'s',r.physical_failures])tr.append(element('td',value));$('#results').append(tr);}for(const s of data.samples){const o=element('option',s.template.replaceAll('_',' ')+' · '+s.sample_id);o.value=s.sample_id;$('#case').append(o);}$('#case').onchange=select;await select();window.galleryReady=true;})();''')


class Handler(SimpleHTTPRequestHandler):
    def log_message(self,*args):pass
    def translate_path(self,path):
        if urlsplit(path).path.startswith('/media/'):
            return str(MEDIA/Path(unquote(urlsplit(path).path)).name)
        return super().translate_path(path)


if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--serve',action='store_true');p.add_argument('--port',type=int,default=8900);a=p.parse_args();build()
    if a.serve:
        server=ThreadingHTTPServer(('127.0.0.1',a.port),functools.partial(Handler,directory=str(OUT)));print('http://127.0.0.1:'+str(a.port)+'/',flush=True)
        try:server.serve_forever()
        except KeyboardInterrupt:server.server_close()
